SELECT wq.id AS id, wq.question_id AS questionId, q.title AS questionTitle, qt_first.category AS questionCategory, q.difficulty AS questionDifficulty, q.question_type AS questionType, wq.wrong_count AS wrongCount, wq.last_wrong_at AS lastWrongAt, wq.mastered AS mastered FROM wrong_question wq LEFT JOIN question q ON q.id = wq.question_id LEFT JOIN ( SELECT qt.question_id, t.category FROM question_tag qt INNER JOIN tag t ON t.id = qt.tag_id AND t.deleted = 0 WHERE qt.id = ( SELECT MIN(qt2.id) FROM question_tag qt2 INNER JOIN tag t2 ON t2.id = qt2.tag_id AND t2.deleted = 0 WHERE qt2.question_id = qt.question_id ) ) qt_first ON qt_first.question_id = q.id WHERE wq.user_id = #{userId}
AND wq.mastered = #{mastered}
ORDER BY wq.mastered ASC, wq.last_wrong_at DESC LIMIT #{offset}, #{pageSize}

